import sys
import math

def find_min_m_and_sets(n, k):
    sets = []
    current_number = k
    while len(sets) < n:
        found_set = False
        for a in range(current_number, 100000, k):
            for b in range(a + k, 100000, k):
                if math.gcd(a, b) != k:
                    continue
                for c in range(b + k, 100000, k):
                    if math.gcd(a, c) != k or math.gcd(b, c) != k:
                        continue
                    for d in range(c + k, 100000, k):
                        if math.gcd(a, d) != k or math.gcd(b, d) != k or math.gcd(c, d) != k:
                            continue
                        found_set = True
                        sets.append((a, b, c, d))
                        current_number = d + k
                        break
                    if found_set:
                        break
                if found_set:
                    break
            if found_set:
                break
    return current_number, sets

def main():
    import sys
    input = sys.stdin.read().strip()
    n, k = map(int, input.split())
    m, sets = find_min_m_and_sets(n, k)
    print(m)
    for s in sets:
        print(*s)

if __name__ == "__main__":
    main()
